begin;
set local search_path=public,extensions;
select no_plan();
update private.whatsapp_worker_configuration set enabled=false;
insert into auth.users(id,email)values('e1220000-0000-0000-0000-000000000001','coex-owner@test.invalid'),('e1220000-0000-0000-0000-000000000002','coex-other@test.invalid');
insert into public.tenants(id,name,slug)values('e1221000-0000-0000-0000-000000000001','Coexistence QA','coexistence-qa');
insert into public.properties(id,tenant_id,name,property_type)values('e1222000-0000-0000-0000-000000000001','e1221000-0000-0000-0000-000000000001','Coexistence Hotel','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e1221000-0000-0000-0000-000000000001','e1220000-0000-0000-0000-000000000001','owner');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1220000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.whatsapp_setup_begin_v2('e1222000-0000-0000-0000-000000000001','coexistence','invalid')$$,'22023',null,'Existing app requires an unambiguous international number');
select set_config('test.coex.session',public.whatsapp_setup_begin_v2('e1222000-0000-0000-0000-000000000001','coexistence','+91 90000 00001')::text,true);
select throws_ok($$select *from private.whatsapp_coexistence_sync$$,'42501',null,'Clients cannot inspect private sync jobs');
select ok(not has_function_privilege('authenticated','public.enqueue_whatsapp_coexistence(text,text,text,jsonb)','EXECUTE'),'Clients cannot forge signed phone-app or history events');
reset role;
set local role service_role;
select set_config('test.coex.claim',public.whatsapp_setup_claim_v2(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001')::text,true);
select is(current_setting('test.coex.claim')::jsonb->>'mode','coexistence','Connection mode comes from the server-bound session');
select is(current_setting('test.coex.claim')::jsonb->>'expected_phone','919000000001','The normalized business number is bound to the session');
select throws_ok($$select public.whatsapp_setup_commit(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001','1221001','1222001','+919999999999',repeat('x',80))$$,'22023',null,'Another shared number cannot replace the expected app number');
select set_config('test.coex.cid',public.whatsapp_setup_commit(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001','1221001','1222001','+919000000001',repeat('x',80))::text,true);
reset role;
select is((select connection_mode from public.whatsapp_connections where id=current_setting('test.coex.cid')::uuid),'coexistence','Coexistence mode committed atomically');
select is((select count(*)::int from private.whatsapp_coexistence_sync where connection_id=current_setting('test.coex.cid')::uuid),2,'Only the two required one-time data requests are queued');
select set_config('test.coex.sync',public.claim_whatsapp_coexistence_sync()::text,true);
select is(current_setting('test.coex.sync')::jsonb->>'kind','smb_app_state_sync','Contact synchronization precedes history');
select lives_ok($$select public.finish_whatsapp_coexistence_sync(current_setting('test.coex.cid')::uuid,'smb_app_state_sync',(current_setting('test.coex.sync')::jsonb->>'lease')::uuid,'requested','request-contacts')$$,'Accepted contact request recorded');
select set_config('test.coex.sync',public.claim_whatsapp_coexistence_sync()::text,true);
select is(current_setting('test.coex.sync')::jsonb->>'kind','history','History can start as soon as contacts were requested');
select lives_ok($$select public.finish_whatsapp_coexistence_sync(current_setting('test.coex.cid')::uuid,'history',(current_setting('test.coex.sync')::jsonb->>'lease')::uuid,'unknown')$$,'Ambiguous outcome is recorded without retry');
select is(public.claim_whatsapp_coexistence_sync(),null,'Single-use accepted and ambiguous requests are never reclaimed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1220000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.retry_whatsapp_coexistence('e1222000-0000-0000-0000-000000000001','history')$$,'22023',null,'Owners cannot blindly repeat an ambiguous one-time request');
reset role;
select is(public.enqueue_whatsapp_coexistence('1221001','wrong-account','history','{}'),null,'Webhook account and phone must both match');
select set_config('test.coex.event',public.enqueue_whatsapp_coexistence('1221001','1222001','history','{"history":[],"metadata":{"phone_number_id":"1221001"}}')::text,true);
select is(public.enqueue_whatsapp_coexistence('1221001','1222001','history','{"metadata":{"phone_number_id":"1221001"},"history":[]}'),null,'Canonical webhook hashing deduplicates retries despite JSON key order');
select set_config('test.coex.job',public.claim_whatsapp_coexistence_event()::text,true);
select throws_ok($$select public.apply_whatsapp_coexistence_batch(current_setting('test.coex.event')::uuid,gen_random_uuid(),0,'[]',0,true)$$,'42501',null,'Wrong import lease cannot apply records');
select set_config('test.coex.records',jsonb_build_array(jsonb_build_object('kind','message','phone','15550000001','source','history','direction','in','id','coex-history-hi','type','text','body','Hi','sent_at',now()-interval '2 days'))::text,true);
select is(public.apply_whatsapp_coexistence_batch(current_setting('test.coex.event')::uuid,(current_setting('test.coex.job')::jsonb->>'lease')::uuid,0,current_setting('test.coex.records')::jsonb,1,true,'{"progress":100}'),1,'A history batch is applied under its lease');
select set_config('test.coex.conv',(select id::text from public.conversations where connection_id=current_setting('test.coex.cid')::uuid and wa_contact_id='15550000001'),true);
select is((select status from public.conversations where id=current_setting('test.coex.conv')::uuid),'closed','Old imported chats do not flood the active Inbox');
select is((select last_inbound_at from public.conversations where id=current_setting('test.coex.conv')::uuid),null,'History never opens the Cloud API reply window');
select is((select guest_id from public.conversations where id=current_setting('test.coex.conv')::uuid),null,'History never verifies a guest identity');
select is((select count(*)::int from public.consent_records where property_id='e1222000-0000-0000-0000-000000000001'),0,'History does not grant marketing or stay consent');
select is((select count(*)::int from private.whatsapp_guest_inbound_jobs j join public.messages m on m.id=j.message_id where m.property_id='e1222000-0000-0000-0000-000000000001'),0,'An old Hi does not run guest commands');
select is((select state from private.whatsapp_coexistence_sync where connection_id=current_setting('test.coex.cid')::uuid and kind='history'),'complete','A late signed history completion resolves an unknown request');
select is((select payload from private.whatsapp_coexistence_events where id=current_setting('test.coex.event')::uuid),'{}'::jsonb,'Processed raw batches are cleared after import');
select lives_ok($$select private.record_whatsapp_coexistence(w,jsonb_build_object('kind','contact','contact_key','phone:15550000001','phone','15550000001','name','Alex','removed',false,'sent_at',now()))from public.whatsapp_connections w where id=current_setting('test.coex.cid')::uuid$$,'Contact sync updates an existing Inbox name');
select is((select contact_name from public.conversations where id=current_setting('test.coex.conv')::uuid),'Alex','Correct phone contact name imported');
select lives_ok($$select private.record_whatsapp_coexistence(w,jsonb_build_object('kind','message','phone','15550000001','source','business_app','direction','out','id','coex-live-phone','type','text','body','Reception here','sent_at',now()))from public.whatsapp_connections w where id=current_setting('test.coex.cid')::uuid$$,'A phone-app reply is recorded as outbound');
select ok((select human_handoff from public.conversations where id=current_setting('test.coex.conv')::uuid),'Recent staff replies in the phone app pause the bot');
select is((select last_inbound_at from public.conversations where id=current_setting('test.coex.conv')::uuid),null,'Staff replies never extend the guest service window');
select lives_ok($$select private.record_whatsapp_coexistence(w,jsonb_build_object('kind','message','phone','15550000001','source','business_app','direction','out','id','coex-live-phone','type','text','body','Duplicate','sent_at',now()))from public.whatsapp_connections w where id=current_setting('test.coex.cid')::uuid$$,'Provider retries are safe');
select is((select count(*)::int from public.messages where wa_message_id='coex-live-phone'),1,'Repeated phone-app echoes create one message');
select lives_ok($$select private.record_whatsapp_coexistence(w,jsonb_build_object('kind','message','phone',null,'source','history','direction','in','id','coex-no-phone','type','text','body','Private unknown contact','sent_at',now()-interval '2 days'))from public.whatsapp_connections w where id=current_setting('test.coex.cid')::uuid$$,'Phone-less identities are held for review');
select is((select count(*)::int from private.whatsapp_coexistence_unmatched where connection_id=current_setting('test.coex.cid')::uuid),1,'Unmatched contact data is retained privately');
select is((select count(*)::int from public.messages where wa_message_id='coex-no-phone'),0,'A BSUID is never mistaken for a guest phone');
select ok(public.route_whatsapp_coexistence_message('1221001','1222001',jsonb_build_object('id','edit-1','timestamp',extract(epoch from now())::bigint::text,'type','edit','edit',jsonb_build_object('original_message_id','coex-live-phone','message',jsonb_build_object('type','text','text',jsonb_build_object('body','Edited reception reply'))))),'Phone-app edits use the original message rather than creating an inbound command');
select is((select body from public.messages where wa_message_id='coex-live-phone'),'Edited reception reply','Edited text is visible in Inbox');
select ok(public.route_whatsapp_coexistence_message('1221001','1222001',jsonb_build_object('id','revoke-1','timestamp',extract(epoch from now())::bigint::text,'type','revoke','revoke',jsonb_build_object('original_message_id','coex-live-phone'))),'Message deletion is handled without guest actions');
select is((select body from public.messages where wa_message_id='coex-live-phone'),'[Message deleted in WhatsApp]','Deleted text is no longer displayed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1220000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.whatsapp_setup_context('e1222000-0000-0000-0000-000000000001')$$,'42501',null,'Another user cannot inspect the hotel import');
select throws_ok($$select public.retry_whatsapp_coexistence('e1222000-0000-0000-0000-000000000001','events')$$,'42501',null,'Another user cannot restart an import');
reset role;
select lives_ok($$select public.whatsapp_coexistence_account_update('1222001','PARTNER_REMOVED',now()-interval '1 day')$$,'Delayed pre-connection removal events are harmless');
select is((select status from public.whatsapp_connections where id=current_setting('test.coex.cid')::uuid),'active','Old removal cannot disable a newer connection');
select lives_ok($$select public.whatsapp_coexistence_account_update('1222001','PARTNER_REMOVED',now()+interval '1 minute')$$,'Meta removal stops the connection');
select is((select status from public.whatsapp_connections where id=current_setting('test.coex.cid')::uuid),'disabled','Meta offboarding stops local delivery');
select is(public.whatsapp_delivery_credential('managed:e1222000-0000-0000-0000-000000000001'),null,'Meta offboarding removes usable credentials');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1220000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.coex.session',public.whatsapp_setup_begin_v2('e1222000-0000-0000-0000-000000000001','coexistence','+919000000001')::text,true);
reset role;
select lives_ok($$select public.whatsapp_setup_claim_v2(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001')$$,'A new authorization can follow Meta offboarding');
select lives_ok($$select public.whatsapp_setup_commit(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001','1221001','1222001','+919000000001',repeat('y',80))$$,'Verified re-onboarding creates a new sync cycle');
select is((select count(*)::int from private.whatsapp_coexistence_sync where connection_id=current_setting('test.coex.cid')::uuid and state='pending'),2,'A new Meta onboarding cycle starts the mandatory requests again');
select is((select count(*)::int from public.messages where wa_message_id='coex-live-phone'),1,'Recorded conversation history survives a new onboarding cycle');
update private.whatsapp_coexistence_sync set state='complete'where connection_id=current_setting('test.coex.cid')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1220000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.whatsapp_setup_disconnect('e1222000-0000-0000-0000-000000000001')$$,'Local disconnect retains the account on Meta');
select set_config('test.coex.session',public.whatsapp_setup_begin_v2('e1222000-0000-0000-0000-000000000001','coexistence','+919000000001')::text,true);
reset role;
select lives_ok($$select public.whatsapp_setup_claim_v2(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001')$$,'Local reconnect obtains a fresh token');
select lives_ok($$select public.whatsapp_setup_commit(current_setting('test.coex.session')::uuid,'e1220000-0000-0000-0000-000000000001','1221001','1222001','+919000000001',repeat('z',80))$$,'Local reconnect keeps the same sender and cycle');
select is((select count(*)::int from private.whatsapp_coexistence_sync where connection_id=current_setting('test.coex.cid')::uuid and state='complete'),2,'Local token renewal never repeats a completed one-time request');
update private.whatsapp_coexistence_sync set state='sending',claimed_at=now()-interval '4 minutes'where connection_id=current_setting('test.coex.cid')::uuid and kind='history';
insert into private.whatsapp_coexistence_events(connection_id,event_key,field,payload,state,claimed_at,attempts)values(current_setting('test.coex.cid')::uuid,'recovery-one','history','{}','processing',now()-interval '4 minutes',1),(current_setting('test.coex.cid')::uuid,'recovery-exhausted','history','{}','processing',now()-interval '4 minutes',5);
select is(private.invoke_whatsapp_coexistence_worker(),null,'Disabled scheduler never sends a network request during recovery');
select is((select state from private.whatsapp_coexistence_sync where connection_id=current_setting('test.coex.cid')::uuid and kind='history'),'unknown','Scheduler recovers a lone expired Meta lease without resending it');
select is((select state from private.whatsapp_coexistence_events where connection_id=current_setting('test.coex.cid')::uuid and event_key='recovery-one'),'pending','Scheduler reclaims an interrupted final import batch');
select is((select state from private.whatsapp_coexistence_events where connection_id=current_setting('test.coex.cid')::uuid and event_key='recovery-exhausted'),'failed','Exhausted imports stop instead of retrying forever');
select *from finish();
rollback;
